drop policy if exists room_reports_insert on public.room_reports; create policy room_reports_insert on public.room_reports for insert to authenticated with check (reporter_id = (select auth.uid()) and exists (select 1 from public.room_members rm where rm.room_id=room_reports.room_id and rm.user_id=(select auth.uid())) and (target_user_id is null or exists (select 1 from public.room_members tm where tm.room_id=room_reports.room_id and tm.user_id=room_reports.target_user_id)));
